const { JSDOM } = require('jsdom');

const dom = new JSDOM('<!DOCTYPE html><div id="app"></div>');
global.document = dom.window.document;
global.window = dom.window;
global.requestAnimationFrame = cb => setTimeout(cb, 1);
global.cancelAnimationFrame = id => clearTimeout(id);

require('@babel/register')({
	ignore: [p => !p.includes('/testbed/')],
	only: [/testbed/]
});

const { render, h } = require('/testbed/src/index.js');
const { useState, useEffect } = require('/testbed/hooks/src/index.js');

let setA;
let effectCalls = 0;
let cleanupCalls = 0;

function Foo() {
	const [a, _setA] = useState(false);
	setA = _setA;
	useEffect(() => {
		effectCalls++;
		return () => {
			cleanupCalls++;
		};
	}, []);
	// setState during render (settling state)
	setA(false);
	return h('button', { onClick: () => setA(true) }, 'Hi');
}

render(h(Foo), document.getElementById('app'));

setTimeout(() => {
	// Simulate click
	setA(true);
	setTimeout(() => {
		console.log('effectCalls:', effectCalls);
		console.log('cleanupCalls:', cleanupCalls);
		if (effectCalls !== 1) {
			console.log('FAIL: effect should run exactly once');
			process.exit(1);
		}
		if (cleanupCalls !== 0) {
			console.log('FAIL: cleanup ran unexpectedly (issue #3567)');
			process.exit(1);
		}
		console.log('PASS');
		process.exit(0);
	}, 50);
}, 50);

