import { act } from 'preact/test-utils';
import { createElement, render } from 'preact';
import { useEffect, useState } from 'preact/hooks';
import { setupScratch, teardown } from '../../../test/_util/helpers';

/** @jsx createElement */

describe('issue 3567 repro', () => {
	/** @type {HTMLDivElement} */
	let scratch;

	beforeEach(() => {
		scratch = setupScratch();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('should not run effect cleanups when settling state during render', () => {
		const cleanup = sinon.spy();
		const effect = sinon.spy(() => cleanup);
		let setA;

		function Foo() {
			const [a, _setA] = useState(false);
			setA = _setA;
			useEffect(effect, []);
			setA(false);
			return <button onClick={() => setA(true)}>Hi</button>;
		}

		render(<Foo />, scratch);
		act(() => {
			setA(true);
		});

		expect(effect).to.be.calledOnce;
		expect(cleanup).to.not.be.called;
	});
});
